b-outage.text:
[
  {
    "title": "Resource exhaustion via complex queries",
    "description": "An attacker repeatedly submits requests designed to trigger computationally expensive database queries on the storefront."
  },
  {
    "title": "Session flooding on login endpoints",
    "description": "An automated script rapidly attempts to create or validate numerous user sessions on the storefront's login mechanisms."
  },
  {
    "title": "API endpoint hammering",
    "description": "An attacker targets non-cached, resource-intensive API endpoints used by the storefront's frontend to fetch product data."
  },
  {
    "title": "Slowloris style connection holding",
    "description": "An attacker opens many connections to the web server and sends partial requests, keeping connections open until the server runs out of available slots."
  },
  {
    "title": "Malicious asset loading",
    "description": "An attacker crafts requests to force the storefront to repeatedly fetch large, non-essential assets or external resources."
  }
]

